// Validate incoming payload from Scriptorium
// Ref: RFC-02 §4.2, §25 (OCR hybride)

const input = $input.first().json;
const body = input.body || input;

const errors = [];

// Required fields
if (!body.schema_version) errors.push('Missing schema_version');
if (!body.request_id) errors.push('Missing request_id');
if (!body.page?.image_base64) errors.push('Missing page.image_base64');
if (!body.prompt?.rendered_text) errors.push('Missing prompt.rendered_text');
if (!body.qc?.verdict) errors.push('Missing qc.verdict');

// Validate model parameter (for benchmark mode)
const validModels = ['default', 'anthropic', 'openai', 'google', 'mistral'];
const requestedModel = body.model || 'default';
if (!validModels.includes(requestedModel)) {
  errors.push(`Invalid model '${requestedModel}'. Must be one of: ${validModels.join(', ')}`);
}

// OCR options (RFC-02 §25)
const includeOcr = body.options?.include_ocr === true;
const ocrFallbackOnly = body.options?.ocr_fallback_only !== false; // default true

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      errors: errors,
      request_id: body.request_id || 'unknown'
    }
  }];
}

// Build OCR prompt section if needed (RFC-02 §25.6)
let systemPrompt = body.prompt.rendered_text;
if (includeOcr) {
  const ocrSection = `\n\n## Extraction du texte (OCR)\n\nEn plus de l'analyse QC, extrais le texte complet de la page.\n- Préserve la structure paragraphes/lignes.\n- Signale les mots illisibles avec [?].\n- Indique la langue détectée.\n\nLe champ \"ocr\" de ta réponse JSON doit inclure :\n- \"extracted\": true\n- \"text\": le texte complet\n- \"language_detected\": code ISO 639-1\n- \"confidence\": 0.0-1.0\n- \"word_count\": nombre de mots\n- \"issues\": array de problèmes détectés (type, position, context)`;
  systemPrompt += ocrSection;
}

// Extract and prepare data for LLM
return [{
  json: {
    valid: true,
    request_id: body.request_id,
    schema_version: body.schema_version,
    // Model selection (for benchmark)
    model: requestedModel,
    // Image data
    image_base64: body.page.image_base64,
    image_mime: body.page.image_mime || 'image/jpeg',
    // Prompt (with OCR section if enabled)
    system_prompt: systemPrompt,
    // OCR options
    include_ocr: includeOcr,
    ocr_fallback_only: ocrFallbackOnly,
    // QC context for reference
    qc_verdict: body.qc.verdict,
    qc_anomalies: body.qc.anomalies || [],
    qc_indicators: body.qc.indicators || {},
    // Book context
    book_id: body.book?.id,
    book_title: body.book?.title,
    page_id: body.page?.page_id,
    // Full payload for logging
    original_payload: body
  }
}];

// Parse and normalize LLM response from Anthropic
// Ref: RFC-02 §5.1, §25 (OCR hybride)

const input = $input.first().json;
const validationData = $('Validate Payload').first().json;

// Check for API error
if (input.error) {
  return [{
    json: {
      success: false,
      error_type: 'llm_error',
      error_details: input.error?.message || JSON.stringify(input.error),
      request_id: validationData.request_id,
      model: 'claude-sonnet-4'
    }
  }];
}

try {
  // Extract text content from Claude response
  const content = input.content?.[0]?.text || '';

  // Parse JSON from response
  let parsed;
  try {
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      parsed = JSON.parse(jsonMatch[0]);
    } else {
      throw new Error('No JSON found in response');
    }
  } catch (e) {
    return [{
      json: {
        success: false,
        error_type: 'parse_error',
        error_details: `Failed to parse JSON: ${e.message}`,
        raw_response: content,
        request_id: validationData.request_id,
        model: 'claude-sonnet-4'
      }
    }];
  }

  // Validate required fields
  const required = ['decision', 'confidence', 'verdict_recommended', 'rationale'];
  const missing = required.filter(f => !parsed[f]);
  if (missing.length > 0) {
    return [{
      json: {
        success: false,
        error_type: 'schema_error',
        error_details: `Missing required fields: ${missing.join(', ')}`,
        raw_response: content,
        request_id: validationData.request_id,
        model: 'claude-sonnet-4'
      }
    }];
  }

  // Build successful response
  const response = {
    success: true,
    schema_version: '1.0.0',
    request_id: validationData.request_id,
    llm: {
      model: 'claude-sonnet-4',
      provider: 'anthropic',
      tokens_in: input.usage?.input_tokens || 0,
      tokens_out: input.usage?.output_tokens || 0,
      cost_eur: ((input.usage?.input_tokens || 0) * 0.000003 + (input.usage?.output_tokens || 0) * 0.000015)
    },
    decision: parsed.decision,
    confidence: parsed.confidence,
    observed_issues: parsed.observed_issues || [],
    verdict_recommended: parsed.verdict_recommended,
    actions_recommended: parsed.actions_recommended || [],
    rationale: parsed.rationale,
    raw_response: content
  };

  // Extract OCR block if present (RFC-02 §25.3)
  if (validationData.include_ocr) {
    const shouldExtract = !validationData.ocr_fallback_only || ['accepte', 'accepte_avec_traitement'].includes(parsed.verdict_recommended);
    if (shouldExtract && parsed.ocr) {
      response.ocr = {
        extracted: true,
        text: parsed.ocr.text || '',
        language_detected: parsed.ocr.language_detected || 'unknown',
        confidence: parsed.ocr.confidence || 0,
        word_count: parsed.ocr.word_count || 0,
        issues: parsed.ocr.issues || []
      };
    } else {
      response.ocr = {
        extracted: false,
        reason: shouldExtract ? 'not_in_response' : 'page_rejected'
      };
    }
  }

  return [{ json: response }];

} catch (e) {
  return [{
    json: {
      success: false,
      error_type: 'unexpected_error',
      error_details: e.message,
      request_id: validationData.request_id,
      model: 'claude-sonnet-4'
    }
  }];
}

